import path from "node:path";
import { createHash } from "node:crypto";
import { createLedger } from "../src/core/objective.js";
import { ROLE_PROFILES } from "../src/core/roles.js";
import { TOOL_GROUPS } from "../src/core/tool_groups.js";
import { BASELINE_CAPABILITIES } from "../src/core/capabilities.js";
import { PLUGIN_TOOL_DEFINITION, addExtensions, dispatch, instrument, makeAgent, makeWorld, routeProbe, sampleArgs, startFakeMcp } from "./helpers/tool_characterization.js";

const OUT = process.env.PROBE_OUT!;
const GROUPS = Object.keys(TOOL_GROUPS);
const ROLES = Object.keys(ROLE_PROFILES);
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const pick = <T,>(xs: T[]): T => xs[Math.floor(rnd() * xs.length)];

test("matrix", async () => {
  const world = makeWorld();
  const mcp = await startFakeMcp();
  const rows: Record<string, string> = {};
  const DELEG = [undefined, ["read_file", "run_command", "enable_tools", "mcp__demo__echo", "custom__stamp", "read_findings"], ["task_completed", "search_code"]];
  const subsets: (string[] | undefined)[] = [undefined, [], ...GROUPS.map((g) => [g]), GROUPS, GROUPS.slice(0, 2)];
  for (let i = 0; i < 500; i++) {
    const role = rnd() < 0.5 ? undefined : pick(ROLES);
    const depth = rnd() < 0.5 ? 0 : 1;
    const groups = pick(subsets);
    const objective = pick(["none", "bare", "req"]);
    const skills = rnd() < 0.5, mask = rnd() < 0.5, ext = rnd() < 0.5;
    const mode = pick(["review", "auto", "read-only"] as const);
    const delegated = pick(DELEG);
    const key = JSON.stringify({ role, depth, groups, objective, skills, mask, ext, mode, delegated });
    const skillDir = path.join(world.home, ".nexus", "skills", "mt2-demo");
    fs.rmSync(skillDir, { recursive: true, force: true });
    if (skills) { fs.mkdirSync(skillDir, { recursive: true }); fs.writeFileSync(path.join(skillDir, "SKILL.md"), "---\nname: mt2-demo\ndescription: x\n---\nDo nothing.\n"); }
    const agent = makeAgent(world, { mode, depth, mask, ...(role ? { role } : {}), ...(delegated ? { delegated } : {}) });
    const a = agent as any;
    if (ext) await addExtensions(agent, mcp.url);
    if (groups) a.enabledToolGroups = new Set(groups);
    if (objective !== "none") { const l = createLedger("x", "2026-01-01T00:00:00.000Z"); l.requirements = objective === "req" ? [{ id: "R1", text: "r", status: "open" } as any] : []; a.objective = l; }
    const t = agent.getEffectiveTools();
    const txt = JSON.stringify(t);
    rows[key] = t.map((x) => x.function.name).join(",") + "|" + createHash("sha256").update(txt).digest("hex").slice(0, 16);
    agent.shutdown();
  }
  await mcp.close(); world.close();
  fs.writeFileSync(OUT + ".matrix.json", JSON.stringify(rows, null, 1));
});

test("handler resolution", async () => {
  const world = makeWorld();
  const mcp = await startFakeMcp();
  const out: Record<string, unknown> = {};
  for (const scenario of ["plain", "ext", "shadow"]) {
    const agent = makeAgent(world, { mode: "auto", fullAccess: true });
    const a = agent as any;
    if (scenario === "ext") await addExtensions(agent, mcp.url);
    if (scenario === "shadow") {
      await agent.initExtensibility();
      a.pluginManager.registerPlugin({ name: "shadow", customTools: BASELINE_CAPABILITIES.map((c) => ({ definition: { type: "function", function: { name: c.modelToolName, description: "shadow", parameters: { type: "object", properties: {} } } }, handler: async () => ({ success: true, output: "plugin-shadow" }) })) });
      a.pluginManager.registerPlugin({ name: "shadow2", customTools: [{ definition: PLUGIN_TOOL_DEFINITION, handler: async () => ({ success: true, output: "x" }) }] });
      await agent.initExtensibility();
    }
    const reg = agent.getCapabilityRegistry();
    const names = reg.listCapabilities().map((c) => c.modelToolName);
    const sources: Record<string, string> = {};
    for (const n of names) sources[n] = routeProbe(agent, n);
    // tag every capability-handler
    for (const n of names) if (reg.getHandler(n) && !agent.getSpine().getHandler(n)) reg.setHandler(n, async () => { probe.trace("run:cap-handler"); return { success: true, output: "<stub>" }; });
    const probe = instrument(agent, world);
    const table: Record<string, unknown> = {};
    for (const n of [...names, "no_such_tool"]) {
      const def = reg.getByToolName(n)?.toolDefinition ?? PLUGIN_TOOL_DEFINITION;
      const o = await dispatch(agent, world, probe, n, sampleArgs(def as any), "approves");
      table[n] = { src: sources[n] ?? "unregistered", status: o.status, ok: o.success, err: (o.error ?? "").slice(0, 80), out: o.output.slice(0, 40), trace: o.trace, cap: reg.getByToolName(n) ? `${reg.getByToolName(n)!.effect}/${reg.getByToolName(n)!.category}` : null };
    }
    out[scenario] = table;
    agent.shutdown();
  }
  await mcp.close(); world.close();
  fs.writeFileSync(OUT + ".handlers.json", JSON.stringify(out, null, 1));
});
